/*
# WrappingLayout — a flow that wraps to new rows

A horizontal flow that WRAPS: children run left to right
`spacing` apart, and when the next one would overflow the view's width it
drops to a new row (`lineSpacing` down; -1, the default, means "same as
spacing"). With room for one row it is a plain row; as the view narrows it
stacks — cards that reflow on a phone with no media query. It owns BOTH
axes of each child (a flow is 2-D); sizes stay the children's own. `justify`
sets each finished row along the flow — `start`, `center`, `end`, or `fill`,
which spreads a row's slack into its gaps the way justified text does;
`indent` and `hangingIndent` inset the first row and every row after it, the
two shapes a paragraph takes.

Division of labor: this is the tool for UNIFORM, replicated collections
that reflow by fitting. Managing NAMED regions per width tier is
ResponsiveLayout's.

Written in Declare over the Layout kernel — the whole strategy is place().

```declare
box: View [ x = 20, y = 20, width = 260,
    layout: WrappingLayout [ spacing = 8, lineSpacing = 8 ],
    View [ width = 70, height = 26, cornerRadius = 6, fill = steelblue ],
    View [ width = 110, height = 26, cornerRadius = 6, fill = cadetblue ],
    View [ width = 90, height = 26, cornerRadius = 6, fill = slategray ],
    View [ width = 120, height = 26, cornerRadius = 6, fill = darkslateblue ]
    ]
```

## spacing
The horizontal gap between children in a row.

## lineSpacing
The vertical gap between rows. **`-1` (the default) means "same as `spacing`"**, so a
uniform grid needs one number rather than two kept in step.

## justify
How a finished row sits along the flow: `start` (the default, left), `center`, `end`
(right), or `fill` — the row's slack is spread evenly into the gaps between its
children, so every full row ends flush at the right edge, as justified text does. As
in text, the LAST row is left at `start` under `fill` (a ragged last line), and a row
of one child has no gap to widen and stays put. A bare literal. (Was `align` until
2026-09-09; `align` now names the cross axis, as it does on every layout.)

## indent
The first row's inset from the left, in pixels — a paragraph's first-line indent. The
first row's usable width shrinks by it; later rows are unaffected (see `hangingIndent`).

## hangingIndent
The inset of every row AFTER the first — a hanging indent, the shape of a bibliography
entry or a wrapped signature whose continuation lines step in under the name. The two
compose: `indent` sets where the first row starts, `hangingIndent` where the rest do.

## align
Where each child sits **within its row**: `start` (the default — the row's top),
`center`, `end`, or `baseline`, which sits every child in the row on one baseline — a
`Text` reports its own, a composite **declares** which part carries it
(`baseline: number = { cap.y + cap.baseline }`), and a child that declares none is
refused by name and placed at the row's top. A row's height grows to hold the
baseline-shifted children. A bare literal.

## place()
Runs the flow, wrapping when the next child would overflow the view's width. **It owns
both axes of each child** — a flow is 2-D — while sizes stay the children's own. A child
never wraps when it is first in its row, so one over-wide child overflows rather than
looping forever. Each finished row starts at its indent, is justified along the flow, and
has its children aligned across it, in one pass over the row.
*/

class WrappingLayout extends Layout [
    spacing: number = 0,
    lineSpacing: number = -1,
    justify: Justify = start,
    align: CrossAlign = start,
    indent: number = 0,
    hangingIndent: number = 0,

    place() {
        const w = this.view == null ? 0 : this.view.width
        const sp = this.spacing
        const ls = this.lineSpacing < 0 ? sp : this.lineSpacing
        const jf = this.justify
        const al = this.align
        const ind0 = Math.max(0, this.indent)
        const indN = Math.max(0, this.hangingIndent)
        const kids = this.laid()
        const out = []
        const heights = []   // per child, for the cross pass over its row
        const bases = []     // per child: its DECLARED baseline, or null
        let cx = ind0
        let cy = 0
        let rowH = 0
        let rowBase = 0
        let firstInRow = true
        let rowStart = 0
        // a finished row [rowStart, end): justify it along the flow, align its
        // children across it, and answer the row's final height — which grows
        // under baseline alignment, since children shift down to the line.
        // `rowW` is where the row's content ends (its indent included); `last`
        // says whether it is the flow's final row, which `fill` leaves ragged.
        const finish = (end, rowW, last) => {
            const slack = Math.max(0, w - rowW)
            if (slack > 0 && (jf == "center" || jf == "end")) {
                const off = jf == "center" ? slack / 2 : slack
                for (let j = rowStart; j < end; j++) out[j].x = out[j].x + off
            } else if (slack > 0 && jf == "fill" && !last) {
                // spread the slack into the gaps: the k-th visible child after
                // the row's first moves by k shares
                let n = 0
                for (let j = rowStart; j < end; j++) if (kids[j].visible) n = n + 1
                if (n > 1) {
                    const share = slack / (n - 1)
                    let k = 0
                    for (let j = rowStart; j < end; j++) { if (!kids[j].visible) continue; out[j].x = out[j].x + share * k; k = k + 1 }
                }
            }
            let lineH = rowH
            if (al == "baseline") {
                lineH = 0
                for (let j = rowStart; j < end; j++) {
                    if (!kids[j].visible) continue
                    const top = bases[j] == null ? 0 : rowBase - bases[j]
                    lineH = Math.max(lineH, top + heights[j])
                }
            }
            for (let j = rowStart; j < end; j++) {
                if (!kids[j].visible) continue
                let off = 0
                if (al == "center") off = (lineH - heights[j]) / 2
                else if (al == "end") off = lineH - heights[j]
                else if (al == "baseline") {
                    if (bases[j] != null) off = rowBase - bases[j]
                    else this.refuseBaseline(kids[j])
                }
                out[j].y = out[j].y + off
            }
            return lineH
        }
        for (let i = 0; i < kids.length; i++) {
            const c = kids[i]
            if (!c.visible) { out.push({ x: cx, y: cy }); heights.push(0); bases.push(null); continue }   // skipped: reclaim its slot
            // the child's FOOTPRINT (scale/rotation composed, position-free —
            // place() must not read the x/y it writes), and the transform's own
            // lead offset, compensated so the visible box lands on the flow
            const f = (c).footprint()
            const cw = f.width
            const ch = f.height
            const leadX = f.x
            const leadY = f.y
            // wrap when this child (with its leading gap) would overflow — never
            // on a row's first child, so one over-wide child just overflows
            if (!firstInRow && cx + sp + cw > w) { const lh = finish(i, cx, false); cx = indN; cy = cy + lh + ls; rowH = 0; rowBase = 0; firstInRow = true; rowStart = i }
            if (!firstInRow) cx = cx + sp
            out.push({ x: cx - leadX, y: cy - leadY })
            heights.push(ch)
            const b = (c).baseline
            bases.push(typeof b == "number" ? b : null)
            if (al == "baseline" && typeof b == "number") rowBase = Math.max(rowBase, b)
            cx = cx + cw
            rowH = Math.max(rowH, ch)
            firstInRow = false
        }
        finish(kids.length, cx, true)   // the last (or only) row — ragged under fill
        return out
        }
    ]

/*
# AppIsland — a whole Declare program running inside a box

`AppIsland` embeds a live Declare application: give it a `program` and it mounts
that program as its own child app — its own reactive graph, input router, and
stage — sized to this view's box. There is no coordinate sync: the tenant fills
the box, so your width/height constraints size it like any view.

It composes `DOMIsland` (the sanctioned foreign-content leaf) and builds the
host's mount key from structured inputs, so callers never hand-splice the
`run:…` wire. The page host (`browser/host-client.js`) sees the key on the box,
resolves the program on its boot ladder — prewarm → cache → in-browser compile,
identical on the dev server and a static host — and renders the child.

`childName` (inherited from `DOMIsland`) is the reverse channel: the running child's
`appName` reflected back up, so a host can title itself by what it shows.

### The bridge

An AppIsland carries the ISLAND BRIDGE (guide ch. 18): declare `external`
attributes on the instance and they pair, by name and with a type handshake,
against the tenant program's own `external` declarations — typed facts both
ways, per settle. `post(topic, payload)` / `onPost(m: IslandPost)` carry the
verbs. `env` and `childName` below are the bridge's untyped ancestors and
still work; new code should declare its surface.

The window frame, activation, and titling belong to the caller — a desktop window
adds an `onPointerDown` that raises itself and reads `childName` for its title; the
homepage and the viewer just size the box. This primitive is only the embedding.

## program
What to run: a program name, a relative path (`"../../calendar/calendar"` reaches the
real app — **no copy of the source, ever**), or the reserved `"__raw__"` live-edit
channel, where the running program is the host app's `liveSource` and recompiles as it
changes. **`""` detaches the island** and nothing mounts, which is how a closed panel
stops paying for its tenant — and what bounds the recursion when a program embeds a
view of itself.

## env
The embedding environment in query form (`"dark=1&base=../x/"`), delivered to the
child's reactive `app.env` at mount **and on every change**. Empty sends none, so the
child keeps its own defaults — leave it alone unless the host genuinely overrides
something, or you will pin the child's appearance against the system's.

## slot
The host's slot marker, derived from `program` and `env` — `run:<program>|<env>` — which is what the island host wires. Nothing to set by hand.
*/

class AppIsland extends DOMIsland [
    program: string = "",
    env: string = "",

    // the host mount key: `run:<program>`, with the env query after `|`. No
    // program → empty slot → the island stays detached (DOMIsland unmounts it).

    slot = { this.program == "" ? "" : "run:" + this.program + (this.env == "" ? "" : "|" + this.env) }
    ]

/*
# Appearance icons — sun, moon, and the half-disc

The Light / System / Dark triad. Five apps built this switch independently and
all five reached for `☀︎ ◐ ☾`, which is the worst case for glyphs: three marks
that must read as ONE family at 14px, drawn by three unrelated parts of whatever
font the platform happens to have. The sun is a heavy sunburst, the moon a thin
crescent, the half-disc a geometric shape — they never matched.

Drawn, they share a circle of the same radius and the same stroke, so they read
as a set: a disc with rays, a disc bitten by a shadow, a disc half filled.
*/



// The three share a disc of one radius. What they do NOT yet share is settled:
// `solid` picks the rendition, and the two are worth comparing on sight rather
// than in prose (test/probe/iconbook.declare shows the set across the weight ramp).
//
// The original argument for filling all three: at 14–18px a 1.6px ring reads far
// lighter than a filled crescent, so filling is what makes them siblings and the
// difference between them is what is SUBTRACTED from the disc — nothing, half, a
// bite. The argument against: a MIXED language — outline sun, outline crescent,
// half-filled disc — is principled, because the half-disc is the one of the
// three whose meaning IS its fill; outlining the other two keeps the triad's
// ink balanced instead of letting the sun and moon carry double the weight.

/*
# SunIcon

"Light" in the appearance triad — a disc with rays, sharing its radius and stroke with
`MoonIcon` and `AutoIcon` so the three read as one family at 14px, which three font
glyphs never did.

## rays
How many rays surround the disc. Eight by default; lowering it reads lighter at small
sizes.

## solid
`false` (the default) draws the ring; `true` fills the disc. **The ring is drawn a
touch smaller than the filled disc on purpose** — a stroke straddles its path, so an
outline at the filled radius reads as the larger mark.

## draw()
Renders the disc and its rays.
*/

class SunIcon extends Icon [
    rays: number = 8,
    solid: boolean = false,         // true = the original filled disc; false = the ring
    draw(d: Draw) {
        d.scale(this.unit, this.unit)
        d.fillStyle = this.ink
        d.strokeStyle = this.ink
        d.lineWidth = this.weight / this.unit
        d.lineCap = "round"
        // The ring is drawn a touch smaller than the solid disc: a stroke straddles
        // its path, so an outline at the filled radius reads as the larger mark.
        d.beginPath()
        d.arc(8, 8, classroot.solid ? 3.5 : 3.15, 0, Math.PI * 2, false)
        if (classroot.solid) d.fill()
        else d.stroke()
        for (let i = 0; i < classroot.rays; i++) {
            const a = (i / classroot.rays) * Math.PI * 2
            const c = Math.cos(a), s = Math.sin(a)
            d.beginPath()
            d.moveTo(8 + c * 5.3, 8 + s * 5.3)
            d.lineTo(8 + c * 6.9, 8 + s * 6.9)
            d.stroke()
            }
        }
    ]


// A crescent built as the region between two equal circles — the outer edge from
// one, the bite from a second offset by (3, -3). Both arcs meet exactly at the
// circles' two intersection points, so the horns close to a point instead of
// leaving the tail an arc pair leaves.
//
// One path, two renditions: FILL it and you get a solid crescent; STROKE the
// same closed path and the horns taper, because the two arcs meet at a point.
// Nothing about the geometry changes — only what is done with it.

/*
# MoonIcon

"Dark" in the appearance triad. The crescent is **the region between two equal
circles**, the second offset by (3, −3) — so both arcs meet exactly at the circles'
intersection points and the horns close to a point instead of leaving the ragged tail
an arc pair leaves.

## solid
`false` (the default) strokes the closed path — the tapered-horn rendition; `true`
fills it for a solid crescent. **One path, two renditions** — nothing about the geometry
changes, only what is done with it.

## draw()
Renders the crescent.
*/

class MoonIcon extends Icon [
    solid: boolean = false,         // true = the original filled crescent; false = the stroked horns
    draw(d: Draw) {
        d.scale(this.unit, this.unit)
        d.beginPath()
        d.arc(8, 8, 5.5, 0.389, 4.323, false)      // outer edge, the long way round
        d.arc(11, 5, 5.5, 3.531, 1.181, true)      // the bite, back to the first horn
        d.closePath()
        if (classroot.solid) { d.fillStyle = this.ink; d.fill() }
        else {
            d.strokeStyle = this.ink
            d.lineWidth = this.weight / this.unit
            d.lineJoin = "round"
            d.stroke()
            }
        }
    ]


/*
# AutoIcon

"System" in the appearance triad — the same disc, half of it taken away. **The ring
stays around the empty half** so it reads as part of one object rather than as a gap.
The one mark of the three whose meaning *is* its fill, which is why a mixed
outline-and-filled language is right for the triad.

## draw()
Renders the half-filled disc.
*/

class AutoIcon extends Icon [
    draw(d: Draw) {
        d.scale(this.unit, this.unit)
        d.strokeStyle = this.ink
        d.fillStyle = this.ink
        d.lineWidth = this.weight / this.unit
        d.beginPath()
        d.arc(8, 8, 5.4, Math.PI * 0.5, Math.PI * 1.5, false)
        d.closePath()
        d.fill()
        d.beginPath()
        d.arc(8, 8, 5.4, 0, Math.PI * 2, false)
        d.stroke()
        }
    ]

/*
# FocusRing

The traveling focus indicator — the OpenLaszlo 3.4 `focusoverlay` line, on the
reactive core, at its third form: a SHAPE-HUGGING rounded outline whose
terminus reshapes to the focused control's own silhouette (library-charter §6
— the ring springs position, size, AND cornerRadius; a Radio's row ring, a
pill Switch's ring, and a text field's ring differ because the targets do).

The layered model (charter, ratified):

- **The fact** — the ring listens to Focus (a `Focus [ onFocusChange(v: View) { … } ]` member) and
  tracks the target's root-space geometry on EVERY change, pointer or
  keyboard. A pointer focus PARKS the ring there silently (snap, no show) —
  so the next Tab's flight departs from the control the user just clicked,
  never from a stale perch.
- **Roles, theme-elected** — `theme.focusRing`: `"both"` (or `true`, the
  default) · `"travel"` (flight + the OL idle fade) · `"rest"` (no flight —
  the ring appears in place and stays) · `false` (no ring; the theme's
  components carry the at-rest indication — the invariant lives with the
  THEME+components pair). While keyboard modality holds and the role includes
  rest, the ring RESTS — no idle fade; a pointer press clears modality and
  the ring hides (web :focus-visible semantics).
- **The flight is the flourish** — `theme.focusAnimate = false` (the
  sampler's "Animate focus transitions" toggle) snaps every move; the
  underdamped travel is default-on.

It arrives automatically with any Control-descended component (the OL
`canvas.focusclass` default); declare your own `FocusRing [ ]` (or subclass)
to replace it. Pure chrome: never focusable, never a pointer target.
(v1 limits, recorded: root-space bounds are summed through the parent chain —
a scrolled container is not compensated; the silhouette is the target's
`cornerRadius` — a `focusShape()` override protocol arrives with the
emulation passes.)

**You do not instantiate this, and you do not position it.** Tab between the controls
below and watch it fly; the members exist for a subclass that replaces the rendition,
and for the theme tokens that elect its behaviour.

```declare
row: View [ x = 20, y = 20,
    layout: SimpleLayout [ axis = x, spacing = 12 ],
    Button [ label = "One" ],
    Button [ label = "Two" ],
    Checkbox [ label = "Three" ]
    ]
```

## shown
Whether the ring is visible. **A pointer focus parks it silently** — geometry current,
ring hidden — so the next Tab departs from the control the user just clicked rather
than from a stale perch.

## placed
Whether the ring has ever had a target to park on. **The first appearance never flies**,
because a flight from nowhere is a streak across the app.

## ringRole()
The theme's election, from `theme.focusRing`: `"both"` (the default), `"travel"`
(flight plus the OpenLaszlo idle fade), `"rest"` (appears in place and stays, no
flight), or `"off"`. **`"off"` is legitimate only when the theme's own controls carry
an at-rest focus indication** — the invariant belongs to the theme-and-components pair,
not to the ring alone.

## restRole()
Whether the elected role includes resting — a resting ring does not idle-fade.

## travelRole()
Whether the elected role includes the flight.

## snapTo()
Lands the ring on its target immediately, skipping the flight. What a pointer focus, a
first appearance, and `theme.focusAnimate = false` all use — **and what a target moving
under a resting ring uses**, so a dragged slider thumb carries the ring rigidly instead
of springing after it.

## overlayUp
True while an overlay owns the keyboard (an open `Menu`). **The ring stands down** —
the menu's own rover is the focus story, and a page ring poking around a panel reads as
chrome fighting chrome.

## idle
True once a travel-role ring has sat still long enough to fade out — the OpenLaszlo
idle behaviour. A resting ring never sets it.

## draw()
Renders the outline: four corner arcs with arms whose length is a pure function of
distance from the target, so the physics does the choreography. Override to replace the
rendition entirely. `theme.focusSights = true` restores the open-bracket "target
sights" reading; `theme.focusRingInnerWidth` adds the Fluent two-tone band.

## tx
**Internal.** The target x the springs chase.

## ty
**Internal.** The target y.

## tw
**Internal.** The target width.

## th
**Internal.** The target height.

## trad
**Internal.** The target corner radius — the silhouette reshapes as the ring travels.

## rad
**Internal.** The ring's current corner radius, sprung toward `trad`.

## gen
**Internal.** The idle-fade generation counter, so a retarget cancels the pending fade.

## visible
Visible while its faded opacity still shows anything, and never while an overlay is up — a ring behind a dialog would point at something you cannot reach.

## theme
The provided design-token record this widget styles off — a **provided value**
(the app provides it once with `App [ theme = { … } ]`; `Control` and the library
widgets read it). Reads `theme.accent` and its kin as typed members; defaults to the
house look. See `Control.theme`.
*/

class FocusRing extends View [
    // The design-token record, a PROVIDED value (docs/system-design/style.md):
    // the app provides it once and this widget reads it, so `theme.x` reads below
    // are plain typed members. Default = the house look (no runtime floor).

    theme: Theme = { this.$provided("theme", SanFrancisco) },
    opacity = 0,

    // an OVERLAY owns the keys (an open menu — Keys.navClaim): the ring
    // stands down while it's up — the menu's rover is the focus story, and
    // a page ring poking around a panel reads as chrome fighting chrome

    overlayUp: boolean = false,
    claims: Keys [ onNavClaim(on: boolean) { classroot.overlayUp = on }
        ],

    // where the ring is HEADED — written by the subscription; the springs chase

    tx: number = 0,
    ty: number = 0,
    tw: number = 0,
    th: number = 0,
    trad: number = 8,
    rad: number = 8,
    shown: boolean = false,
    placed: boolean = false,                     // has the ring EVER had a target to park on?

    // the OL idle fade — TRAVEL role only; a resting ring does not fade

    idle: boolean = false,
    gen:  number = 0,

    // role helpers over the theme election

    ringRole()  { const r = this.theme.focusRing; return r == false ? "off" : r == true || r == null ? "both" : r },
    restRole()  { const r = this.ringRole(); return r == "both" || r == "rest" },
    travelRole() { const r = this.ringRole(); return r == "both" || r == "travel" },

    snapTo() { this.x = this.tx; this.y = this.ty; this.width = this.tw; this.height = this.th; this.rad = this.trad },

    // the target's LIVE silhouette, root-space, from the service's follower —
    // tracked through the parent chain and focusShape(), so an arrow-keyed
    // slider thumb (or a reflowing layout) moves the resting ring with it.
    // The band sits OUTSIDE the silhouette: inner edge touching the control's
    // boundary (the Mac halo's hug), displaced by gap + half the stroke.

    focus: Focus [
        onGeometry(g: FocusGeometry) {
            if (g.root != this.root) return
            // TRAVEL WITH the target's scroller: the ring's surface re-hosts
            // inside the scrolled container and positions in ITS content
            // coordinates — the platform then carries ring and control
            // together, zero lag, no per-scroll re-derive (the sticky-frame
            // inverse). A backend without the ride keeps root-space reactive
            // positioning.
            const prev = (this)._lastTarget
            const prevHome = (this)._lastHome
            const hadHome = (this)._hasHome === true
            const px = classroot.x
            const py = classroot.y
            const homed = classroot.travelWith(g.scroller)
            const gx = homed ? g.homeX : g.x
            const gy = homed ? g.homeY : g.y
            // Crossing scroll HOMES (the bar's button → a control in the
            // scrolled page): the flight must still fly. The ring's current
            // position converts through ROOT space into the DESTINATION
            // home's coordinates — same painted spot, new numbers — and the
            // springs then travel entirely within the new space (correct
            // even if that pane scrolls mid-flight).
            if (hadHome && prevHome != g.scroller) {
                const toRoot = prevHome == null || prevHome == this.root
                    ? ({ x: px, y: py })
                    : (() => { const o = prevHome.rootOrigin(); return ({ x: o.x + px - prevHome.scrollX, y: o.y + py - prevHome.scrollY }) })()
                const dst = !homed || g.scroller == this.root
                    ? toRoot
                    : (() => { const o = g.scroller.rootOrigin(); return ({ x: toRoot.x - o.x + g.scroller.scrollX, y: toRoot.y - o.y + g.scroller.scrollY }) })()
                classroot.x = dst.x
                classroot.y = dst.y
                }
            const gap = typeof classroot.theme.focusRingGap == "number" ? classroot.theme.focusRingGap : 0
            const lw = typeof classroot.theme.focusRingWidth == "number" ? classroot.theme.focusRingWidth : 3
            const iw = typeof classroot.theme.focusRingInnerWidth == "number" ? classroot.theme.focusRingInnerWidth : 0
            const off = gap + iw + lw / 2
            // a traveled ring draws the CONTENT-space box (homeW/homeH/homeRad):
            // any ancestor transform above the scroller reaches its surface
            // through the platform, so frame-space extents would double-apply it
            classroot.tx = gx - off; classroot.ty = gy - off
            classroot.tw = (homed ? g.homeW : g.w) + 2 * off; classroot.th = (homed ? g.homeH : g.h) + 2 * off
            classroot.trad = (homed ? g.homeRad : g.rad) + off
            // Only a FOCUS CHANGE flies. The same control moving under a resting
            // ring — a dragged slider thumb, a reflow — takes the ring with it
            // rigidly: the springs' targets just moved, so land them NOW. The
            // discriminator is target IDENTITY (a handler-scratch expando — not
            // reactive state, just the previous event's view for comparison).
            ;(this)._lastTarget = g.view
            ;(this)._lastHome = g.scroller
            ;(this)._hasHome = true
            if (prev == g.view) classroot.snapTo()
            },

        onFocusChange(v: View) {
            if (v == null) { classroot.shown = false; return }
            let n = v
            for (; n != null && n.parent != null; n = n.parent) { }
            // Another app on the page (an embedded preview) owns this target — its own
            // ring indicates it; this one stands down rather than chase foreign coordinates.
            if (n != this.root) { classroot.shown = false; return }
            // Pointer focus: PARK silently — geometry current, ring hidden. The next
            // keyboard flight departs from here (the just-clicked control).
            if (!Focus.byKeyboard()) { classroot.shown = false; classroot.snapTo(); classroot.placed = true; return }
            if (classroot.ringRole() == "off") { classroot.shown = false; return }
            // No flight when: the ring has never been placed, the theme suppressed
            // the flourish, or the role is rest-only (appear in place, stay).
            if (!classroot.placed || classroot.theme.focusAnimate == false || !classroot.travelRole()) classroot.snapTo()
            classroot.placed = true
            classroot.shown = true
            classroot.raise()     // chrome stays chrome: above whatever raised last (a Dialog, a Menu)
            // idle fade only for the travel-only role — a resting ring persists
            if (classroot.restRole()) { classroot.idle = false; return }
            classroot.gen = classroot.gen + 1
            const g2 = classroot.gen
            classroot.idle = false
            setTimeout(() => { if (classroot.gen == g2) classroot.idle = true }, 1000)
            }
        ],

    // the travel: underdamped springs = motion toward the target + a little
    // arrival overshoot — the 3.4 bounce, by physics. The radius travels too:
    // the terminus reshapes to the control it surrounds.

    Spring [ attribute = x,      to = { classroot.tx }, stiffness = 220, damping = 16 ],
    Spring [ attribute = y,      to = { classroot.ty }, stiffness = 220, damping = 16 ],
    Spring [ attribute = width,  to = { classroot.tw }, stiffness = 220, damping = 18 ],
    Spring [ attribute = height, to = { classroot.th }, stiffness = 220, damping = 18 ],
    Spring [ attribute = rad,    to = { classroot.trad }, stiffness = 220, damping = 20 ],

    Spring [ attribute = opacity, to = { classroot.shown && !classroot.idle ? 0.9 : 0 }, stiffness = 90, damping = 20 ],

    visible = { this.opacity > 0.02 && !this.overlayUp },

    // pure chrome: never a pointer target — and never on the hover chain
    // either, which is what pointerEvents (unlike a hit-test override) governs

    pointerEvents = "none",

    // the shape-hugging outline — a rounded rect at the sprung radius, drawn,
    // so it re-derives as the radius travels between silhouettes

    // the OL brackets and the shape-hugging outline are ONE rendition at two
    // coverages: four corner-anchored strokes whose straight arms extend
    // toward each edge's midpoint by cov ∈ (0..1]. cov = 1 → arms meet, a
    // closed outline; cov low → open corner brackets ("target sights").
    // Coverage is a pure function of DISTANCE from target, so the physics
    // does the choreography: a flight breaks the ring open mid-air and the
    // settle closes the sights around the new silhouette. Small targets skip
    // the bracket phase (a ring around a radio dot has no arms to open).

    draw(d: Draw) {
        const w = this.width, h = this.height
        const Q = Math.PI / 2
        const dist = Math.abs(this.x - this.tx) + Math.abs(this.y - this.ty) + Math.abs(this.width - this.tw) + Math.abs(this.height - this.th)
        const small = Math.min(w, h) < 40
        // Ruled 2026-07-17: the ring travels as a CLOSED outline, source shape
        // to destination shape — no bracket mode intervening. The sights
        // rendition survives behind `theme.focusSights = true` (data, not a
        // code path) for its possible return: fully open in motion, arms
        // sweeping shut inside the last 16px of settle.
        const cov = this.theme.focusSights == true && !small ? Math.max(0.22, 1 - dist / 16) : 1
        const lw = typeof this.theme.focusRingWidth == "number" ? this.theme.focusRingWidth : 3
        // The indicator is ONE band or TWO, by data: `focusRingInnerWidth` > 0
        // adds an inner stroke between the control and the outer one — the
        // Fluent (Redmond) two-tone focus rectangle, black over white. Both
        // passes are the same outline at different insets; the flight, the
        // sights, and the silhouette machinery are shared, not forked.
        const iw = typeof this.theme.focusRingInnerWidth == "number" ? this.theme.focusRingInnerWidth : 0
        const pass = (ins, lwp, color) => {
            const r = Math.max(1, Math.min(this.rad - ins, Math.min(w, h) / 2 - ins))
            const ax = Math.max(0, ((w - 2 * ins) / 2 - r) * cov)      // horizontal arm length
            const ay = Math.max(0, ((h - 2 * ins) / 2 - r) * cov)      // vertical arm length
            d.strokeStyle = color
            d.lineWidth = lwp
            d.beginPath()
            // each corner: arc + arms, inset symmetrically
            d.moveTo(ins + r + ax, ins); d.lineTo(ins + r, ins); d.arc(ins + r, ins + r, r, -Q, Math.PI, true); d.lineTo(ins, ins + r + ay)
            d.moveTo(w - ins - r - ax, ins); d.lineTo(w - ins - r, ins); d.arc(w - ins - r, ins + r, r, -Q, 0); d.lineTo(w - ins, ins + r + ay)
            d.moveTo(w - ins, h - ins - r - ay); d.lineTo(w - ins, h - ins - r); d.arc(w - ins - r, h - ins - r, r, 0, Q); d.lineTo(w - ins - r - ax, h - ins)
            d.moveTo(ins + r + ax, h - ins); d.lineTo(ins + r, h - ins); d.arc(ins + r, h - ins - r, r, Q, Math.PI); d.lineTo(ins, h - ins - r - ay)
            d.stroke()
            }
        pass(0, lw, typeof this.theme.focusColor == "number" ? this.theme.focusColor : this.theme.accent)
        if (iw > 0) pass((lw + iw) / 2, iw, typeof this.theme.focusRingInnerColor == "number" ? this.theme.focusRingInnerColor : this.theme.surface)
        }
    ]

/*
# Declare docs

The Declare reference, rendered AS a Declare app — self-hosted: Declare
documenting Declare. It loads docs-model.json — the extractor's output
(tools/internal/doc/extract.mjs), one walkable data structure — and renders a
navigable class reference: a left rail of components, a detail pane with each
class's Markdown prose and an attributes table, every doc string rendered by
the runtime Markdown component. This one app is both the in-browser docs and
(once built) the web docs; the live object browser is this same view reached
from an instance.

`{ }` bodies are TypeScript → `0x…` colors and expressions; `[ ]` literal
slots take `#…` / named colors. Every color reads `theme.<token>` — one
provided record on the App (see it there), so the whole document reskins
from one place.
*/

use [ SunIcon, AutoIcon, MoonIcon ]

/*
## Type tokens

Selection is a PROVIDED value: these tokens don't opt in themselves — the
detail pane sets `selectable = true` on its container, so all right-pane text
(including Markdown prose) is selectable, while the left rail stays
unselectable chrome.
*/

class Title extends Text [ fontFamily = ["system-ui", "sans-serif"],
    fontWeight = semibold, textColor = { this.$provided("theme").text }
    ]


class Muted extends Text [ fontFamily = ["system-ui", "sans-serif"],
    textColor = { this.$provided("theme").textMuted }
    ]


class Mono extends Text [ fontFamily = ["ui-monospace, SFMono-Regular, monospace", "ui-monospace", "monospace"] ]

// a component tab in the left rail — selection is one App attribute
// (`app.selected`, the class name); a tab lights when it matches and sets it
// on click, so the whole navigator is one string

class ClassTab extends View [ width = { parent.width }, height = 30, cornerRadius = 6,
    cname:   string = "",
    lit: boolean = { this.root.mode == "reference" && this.root.selected == classroot.cname },
    fill = { this.lit ? this.$provided("theme").sel : this.hovered ? this.$provided("theme").control : null },
    onClick()     { this.root.refAt = classroot.cname; this.root.location = "reference/" + classroot.cname; this.root.showPage() },
    lbl: Mono [ x = 24, y = 7, fontSize = 14, wrap = false,
        text = { classroot.cname },
        textColor = { classroot.lit ? this.$provided("theme").text : this.$provided("theme").tabIdle } ]
    ]


/* A rail group's head — the line that folds it. A group is OPEN when it holds the
   current page, closed otherwise; a click overrides that, and the override holds
   until the next navigation (its key is the page it was made on), so folding a
   group never fights the rail when you land somewhere new. One class serves the
   guide's parts, the language's form groups, and the class groups alike. */

class FoldHead extends View [ width = { parent.width }, height = 28, cornerRadius = 6, cursor = "pointer",
    label:    string  = "",
    contains: boolean = false,             // does this group hold the current page?
    manual:   boolean = false,             // the reader's fold, …
    manualAt: string  = "",                // … keyed by the page it was made on
    open:     boolean = { classroot.manualAt == this.root.page ? classroot.manual : classroot.contains },
    fill = { this.hovered ? this.$provided("theme").control : null },
    onClick() { this.manual = !this.open; this.manualAt = this.root.page },
    mark: Mono [ x = 8, y = 8, fontSize = 10, wrap = false, textColor = { this.$provided("theme").textMuted },
        text = { classroot.open ? "\u25BC" : "\u25B6" } ],
    lbl: Text [ x = 24, y = 6, fontFamily = ["system-ui", "sans-serif"], fontSize = 14, fontWeight = semibold, wrap = false,
        text = { classroot.label },
        textColor = { classroot.contains ? this.$provided("theme").text : this.$provided("theme").tabIdle } ]
    ]


// one topic of classes in the reference rail (model.classGroups — extract's CLASS_GROUPS)

class ClassGroup extends View [ width = { parent.width },
    layout: SimpleLayout [ axis = y, spacing = 2 ],
    head: FoldHead [ label = { "" + this.$data(["name"]) },
