class DocField extends TextInput [ multiline = true, spellcheck = false, wrap = false,
    fontFamily = ["ui-monospace, SFMono-Regular, monospace", "ui-monospace", "monospace"], fontSize = { 13 * this.root.fontScale }, textColor = { this.$provided("theme").code },   // 13 = the house code size (PROSE.codeSize)
