/*
## Inline examples, woven through the prose

Every `declare` code fence in any prose that compiles (as-is, or wrapped in
`App […]`) becomes a `RunIsland`: the source above, its live preview below —
edit and it re-runs. The extractor wrote its source to
`apps/docs/demos/<id>.declare`, so the host seeds and mounts it exactly
like the homepage's demos. `live` (threaded from the page) keeps the
preview's slot empty until its page is the one on screen, so only the visible
page's islands ever compile.
*/

class RunIsland extends View [ width = { parent.width },
    rid:    string  = { this.$data(["id"]) },
    rsrc:   string  = { this.$data(["source"]) },
    rlines: number  = { this.$data(["lines"]) },
    rstage: number  = { this.$data(["stageH"]) || 200 },   // extractor-measured stage height — the frame FITS the settled app
    live:   boolean = false,

    // this island's edit is the one that failed to compile — the host publishes the
    // report on app.liveReport (cleared by a clean compile), keyed by app.liveCard

    broken: boolean = { this.root.liveCard == this.rid && this.root.liveReport != "" },
    layout: SimpleLayout [ axis = y, spacing = 0 ],   // the preview frame abuts the code block, no gap

    // same code-box grammar as a static block (chipBg tint, 8px radius, 13px face),
    // marked live/editable by the amber bar + label (a read-only block is teal).

    // height: measured 15px/line at the 13px code face, plus the field's ~20px
    // padding and the 46+8 header/footer chrome — so the code fits without an
    // inner scrollbar up to the cap

    editor: View [ width = { parent.width }, fill = { this.$provided("theme").chipBg },
        height = { Math.min(classroot.rlines * 15 * this.root.fontScale + 93, 900) },
        bar:  View [ x = 0, y = 0, width = 3, height = { parent.height }, fill = { classroot.broken ? this.$provided("theme").errBar : 0xE6B450 } ],
        tag:  View [ x = 18, y = 7, height = 17, cornerRadius = 3, fill = 0xE6B450,
            lbl: Mono [ x = 7, y = 3, fontSize = 10, letterSpacing = 1, fontWeight = semibold, textColor = 0x1A1A1A,
                text = "LIVE · EDITABLE", wrap = false ],
            width = { this.lbl.width + 14 }
            ],

        // Revert restores the pristine source and republishes it — the way back the
        // guide owes a reader it just told to break something

        rev: View [ y = 5, height = 20, cornerRadius = 6, stroke = { stroke(1, this.$provided("theme").line) },
            x = { parent.width - this.width - 10 },
            width = { this.rlbl.width + 16 },
            fill = { this.hovered ? this.$provided("theme").control : null },
            onClick() { classroot.editor.field.text = classroot.rsrc
                        this.root.liveCard = classroot.rid
                        this.root.liveSource = classroot.rsrc },
            rlbl: Text [ x = 8, y = 3, fontFamily = ["system-ui", "sans-serif"], fontSize = 11, fontWeight = semibold,
                textColor = { parent.hovered ? this.$provided("theme").text : this.$provided("theme").textMuted }, text = "Revert" ]
            ],
        hint: Muted [ y = 9, fontSize = { 11 * this.root.fontScale }, italic = true, text = "runs live below ↓",
            x = { parent.rev.x - this.width - 12 } ],

        // a line of breathing room below the label before the code starts

        field: DocField [ x = 18, y = 46, width = { parent.width - 30 }, height = { parent.height - 54 },
            editName = { classroot.rid }, src = { classroot.rsrc } ]
        ],

    // the compile report, at the island — the diagnostic is a teaching surface, so a
    // broken edit shows its error right here (the last good render stays below it)

    err: View [ width = { parent.width }, fill = { this.$provided("theme").errBg },
        visible = { classroot.broken },
        height = { this.msg.height + 20 },
        bar: View [ x = 0, y = 0, width = 3, height = { parent.height }, fill = { this.$provided("theme").errBar } ],
        msg: Text [ x = 18, y = 10, width = { parent.width - 36 }, wrap = true,
            fontFamily = ["ui-monospace, SFMono-Regular, monospace", "ui-monospace", "monospace"], fontSize = { 12 * this.root.fontScale },
            textColor = { this.$provided("theme").errText }, text = { this.root.liveReport } ]
        ],

    stage: View [ width = { parent.width }, height = { classroot.rstage }, fill = { this.$provided("theme").chipBg },
        run:     AppIsland [ width = { parent.width }, height = { parent.height },
            program = { classroot.live ? classroot.rid : "" } ],
        divider: View [ x = 0, y = 0, width = { parent.width }, height = 2, fill = { this.$provided("theme").rule } ],
        spine:   View [ x = 0, y = 0, width = 3, height = { parent.height }, fill = 0xE6B450 ]
        ]
    ]


// one prose segment — a run of Markdown text OR (0-or-1) a runnable island. A code
// block that didn't compile stays folded into the Markdown as a static code fence.
// `tone`/`lead` let a caller dim the prose (the reference runs dimmer than the guide).

class Block extends View [ width = { parent.width },
    live: boolean = false,
    tone: Color   = { this.$provided("theme").body },
    lead: number  = 1.6,
    layout: SimpleLayout [ axis = y, spacing = 14 ],
    md: Markdown [ width = { parent.width }, lineHeight = { classroot.lead }, bodyColor = { classroot.tone }, scale = { this.root.fontScale }, dark = { this.root.darkUI },
        visible = { this.$data(["md"]) != "" }, text = { this.$data(["md"]) },
        onLink(href: string) { this.root.openDocLink(href) }
        ],
    RunIsland [ datapath = :code[], width = { parent.width }, live = { classroot.live } ]
    ]


/*
## The class page

One class's whole detail page. A single instance exists — the use site
(refCol, below) computes the SELECTED class's model node as its datapath, so
switching classes re-roots this subtree and constructs exactly the page being
read. (The pre-2026-08-08 shape built every class's page up front and picked
one with `visible`; the whole reference priced every boot.)
*/

class ClassDetail extends View [ width = { parent.width },
    cname: string = "",
    visible = { this.root.selected == classroot.cname },

    // this page is on screen — the gate every inline preview reads before it mounts

    pageLive: boolean = { this.root.mode == "reference" && this.root.selected == classroot.cname },
    hasBase:  boolean = { this.$data(["extends"]) != null },
    layout: SimpleLayout [ axis = y, spacing = 36 ],

    // the ancestor projections as DECLARED data (the value-root idiom), so the
    // chain row and the strips can replicate over them

    ancestry:  Dataset [ contents = { { items: this.root.ancestryOf(classroot.cname) } } ],
    ancestors: Dataset [ contents = { { items: this.root.ancestorsOf(classroot.cname) } } ],

    /* ### Header — the class, where it sits, and its opener */

    header: View [ width = { parent.width },
        layout: SimpleLayout [ axis = y, spacing = 12 ],
        Eyebrow [ text = { "REFERENCE · " + (this.$data(["origin"]) == "library" ? "STANDARD LIBRARY" : "BUILT-IN") + (this.$data(["source"]) != null ? " · " + this.$data(["source"]) : "") } ],
        Title [ fontSize = { 32 * this.root.fontScale }, text = { classroot.cname } ],

        // the chain, every ancestor a link — and the class's siblings and subclasses

        // (re-rooted to the ancestry data, so its visibility reads the page's fact, not a path)

        chain: View [ width = { parent.width }, visible = { classroot.hasBase },
            datapath = { classroot.ancestry.value },
            layout: WrappingLayout [ spacing = 8, lineSpacing = 8, align = baseline ],
            Mono [ fontSize = { 14 * this.root.fontScale }, textColor = { this.$provided("theme").sigDim }, text = { "class " + classroot.cname + " extends" } ],
            Link [ datapath = :items[] ]
            ],
        base: Mono [ fontSize = { 14 * this.root.fontScale }, textColor = { this.$provided("theme").sigDim }, visible = { this.$data(["extends"]) == null },
            text = { "class " + classroot.cname + "  (base)" } ],
        subs: View [ width = { parent.width }, visible = { this.$data(["subclasses","length"]) > 0 },
            layout: WrappingLayout [ spacing = 6, lineSpacing = 6, align = baseline ],
            Muted [ fontSize = { 13 * this.root.fontScale }, text = "subclasses:" ],
            Chip [ datapath = :subclasses[], kind = "class", cls = { "" + this.$data("") }, label = { "" + this.$data("") } ]
            ],
        sibs: View [ width = { parent.width }, visible = { this.$data(["siblings","length"]) > 0 },
            layout: WrappingLayout [ spacing = 6, lineSpacing = 6, align = baseline ],
            Muted [ fontSize = { 13 * this.root.fontScale }, text = { "also extends " + this.$data(["extends"]) + ":" } ],
            Chip [ datapath = :siblings[], kind = "class", cls = { "" + this.$data("") }, label = { "" + this.$data("") } ]
            ],

        // the class prose — dimmed, with any inline runnable examples woven in

        Block [ datapath = :docSegs[], width = { parent.width },
            live = { classroot.pageLive }, tone = { this.$provided("theme").refDim }, lead = 1.6 ]
        ],

    // the page's sections, one line: for the reader who came for a fact

    jump: View [ width = { parent.width },
        layout: WrappingLayout [ spacing = 8, lineSpacing = 8, align = baseline ],
        Muted [ fontSize = { 16 * this.root.fontScale }, text = "On this page" ],
        JumpLink [ label = "Usage",      visible = { this.$data(["example","length"]) > 0 },    count = { this.$data(["example","length"]) },    to = { classroot.usage } ],
        JumpLink [ label = "Attributes", visible = { this.$data(["attributes","length"]) > 0 }, count = { this.$data(["attributes","length"]) }, to = { classroot.attrs } ],
        JumpLink [ label = "Methods",    visible = { this.$data(["methods","length"]) > 0 },    count = { this.$data(["methods","length"]) },    to = { classroot.meths } ],
        JumpLink [ label = "Events",     visible = { this.$data(["events","length"]) > 0 },     count = { this.$data(["events","length"]) },     to = { classroot.evts } ],
        JumpLink [ label = "Provided",   visible = { classroot.hasReads },     count = { this.$data(["reads","theme","length"]) + this.$data(["reads","provided","length"]) }, to = { classroot.reads } ],
        JumpLink [ label = "Inherited",  visible = { this.$data(["chain","length"]) > 1 },      count = { this.$data(["chain","length"]) - 1 }, to = { classroot.inh } ]
        ],

    /* ### Usage — the class at work, live: each example runs, and its source is editable */

    usage: View [ width = { parent.width }, visible = { this.$data(["example","length"]) > 0 },
        layout: SimpleLayout [ axis = y, spacing = 28 ],
        SectionHead [ head = "Usage", note = "The class as you would write it. Every example runs below its source, and the source is yours to edit." ],
        Example [ datapath = :example[], width = { parent.width }, live = { classroot.pageLive } ]
        ],

    /* ### The members, in three ruled sections — an override sits in its own
           section, with the ancestor's slot linked under its signature */

    attrs: View [ width = { parent.width }, visible = { this.$data(["attributes","length"]) > 0 },
        layout: SimpleLayout [ axis = y, spacing = 22 ],
        SectionHead [ head = "Attributes",
            note = { this.$data(["attributes","length"]) + " on " + classroot.cname + (this.root.hasOverrides(this.$data(["attributes"])) ? " — its own first, then the inherited ones it gives a new default" : "") } ],
        AttrRow [ datapath = :attributes[], width = { parent.width }, live = { classroot.pageLive } ]
        ],

    meths: View [ width = { parent.width }, visible = { this.$data(["methods","length"]) > 0 },
        layout: SimpleLayout [ axis = y, spacing = 22 ],
        SectionHead [ head = "Methods", note = { this.$data(["methods","length"]) + " on " + classroot.cname } ],
        MethodRow [ datapath = :methods[], width = { parent.width }, live = { classroot.pageLive } ]
        ],

    evts: View [ width = { parent.width }, visible = { this.$data(["events","length"]) > 0 },
        layout: SimpleLayout [ axis = y, spacing = 22 ],
        SectionHead [ head = "Events", note = { this.$data(["events","length"]) + " on " + classroot.cname } ],
        EventRow [ datapath = :events[], width = { parent.width }, live = { classroot.pageLive } ]
        ],

    /* ### Provided — what the class READS from above: its contract with its container */

    hasReads: boolean = { this.$data(["reads","theme","length"]) + this.$data(["reads","provided","length"]) > 0 || this.root.ancestorsOf(classroot.cname).some((a) => a.n > 0) },
    reads: View [ width = { parent.width }, visible = { classroot.hasReads },
        layout: SimpleLayout [ axis = y, spacing = 18 ],
        SectionHead [ head = "Provided",
            note = { "The values " + classroot.cname + " reads from above — its dependencies on whatever contains it. Change one on any ancestor and it follows. Its own body's reads; an ancestor that reads values of its own is folded beneath." } ],
        tokens: View [ width = { parent.width }, visible = { this.$data(["reads","theme","length"]) > 0 },
            layout: WrappingLayout [ spacing = 6, lineSpacing = 6, align = baseline ],
            Chip [ datapath = :reads.theme[], kind = "token", label = { "theme." + this.$data("") } ]
            ],
        provided: View [ width = { parent.width }, visible = { this.$data(["reads","provided","length"]) > 0 },
            layout: WrappingLayout [ spacing = 6, lineSpacing = 6, align = baseline ],
            Chip [ datapath = :reads.provided[], kind = "token", label = { "" + this.$data("") } ]
            ],
        strips: View [ width = { parent.width }, datapath = { classroot.ancestors.value },
            layout: SimpleLayout [ axis = y, spacing = 8 ],
            ReadStrip [ datapath = :items[] ]
            ]
        ],

    /* ### Inherited — per ancestor, names only, folded */

    inh: View [ width = { parent.width }, visible = { this.$data(["chain","length"]) > 1 },
        layout: SimpleLayout [ axis = y, spacing = 14 ],
        SectionHead [ head = "Inherited",
            note = { "Everything else " + classroot.cname + " can do, by the class it comes from. Names only — each is a link to its own entry; the ancestor's documentation stays on the ancestor's page." } ],
        strips: View [ width = { parent.width }, datapath = { classroot.ancestors.value },
            layout: SimpleLayout [ axis = y, spacing = 14 ],
            Strip [ datapath = :items[] ]
            ]
        ],

    tail: View [ width = { parent.width }, height = 48 ]
    ]


/*
## The language pages

A third mode over the same model (its own locations, `language/<form>`, but no
tab of its own — the forms head the reference rail): every keyword, delimiter,
operator, and member shape the grammar accepts, from the registry
(tools/internal/doc/forms.md → model.forms). The rail lists them by group; the page is one form: its syntax in
a code box, its lead, live usage, the RULES the compiler enforces — each quoting the
checker's own sentence — and what it relates to. With no form selected the pane
shows the index: every form, grouped, one line each.
