    // top with the viewport would eat that margin. Every switch path routes through
    // here: rail tabs and prose links alike.

    showPage() { this.detail.top.scrollIntoView() },

    // An in-app doc link is a location WRITE (docs/system-design/location.md §5) — it navigates
    // the app exactly like a rail tab, so it deep-links, shares, and back-buttons. It
    // also keeps the remembered cursor in step (like the tabs). External schemes still
    // leave through `navigate`.

    openDocLink(href: string) {
        if (!href.startsWith("declare-docs:")) { this.root.navigate(href); return }
        const id = href.slice("declare-docs:".length)
        if (id.startsWith("guide:")) {                       // guide:tree → the chapter whose id ends with the slug
            const slug = id.slice("guide:".length)
            const hit = (this.root.docs.read(["guide"]) || []).find(c => c.id.replace(/^\d+-/, "") == slug)
            if (hit) { this.root.guideAt = hit.id; this.root.location = "guide/" + hit.id; this.root.showPage() }
            return
        }
        if (id == "reference:index") { this.root.location = "reference/" + this.root.refAt; this.root.showPage(); return }
        if (id.startsWith("language:")) {                    // language:class → the form's page ("language:" alone → the index)
            const slug = id.slice("language:".length)
            this.root.formAt = slug; this.root.location = "language/" + slug; this.root.showPage(); return
        }
        if (!id.includes(":")) {                             // a reference symbol: View / View.width
            this.root.refAt = id.split(".")[0]; this.root.location = "reference/" + this.root.refAt; this.root.showPage(); return
        }
        if (id.startsWith("operational:")) { this.root.navigate("docs/operational/" + id.slice("operational:".length) + ".md"); return }
        if (id == "spec:core") { this.root.navigate("docs/declare.md"); return }
        if (id == "essay:why-declare") { this.root.navigate("apps/homepage/homepage.declare") }
        },

    /* ## The chrome bar
       The house header — Viewer's and Tracker's bar, on this app: brand at 20
       (gradient "Declare", solid "Docs"), the SEARCH PILL centered, and the
       type-size stepper + theme switch on the right (both moved up out of the
       rail, where Viewer keeps them too). */

    bar: View [ x = 0, y = 0, width = { this.root.hostWidth }, height = { this.root.barH }, fill = { this.$provided("theme").rail },
        hair: View [ x = 0, y = { this.root.barH - 1 }, width = { parent.width }, height = 1, fill = { this.$provided("theme").edge } ],

        brand: View [ x = 20, y = { (this.root.barH - 22) / 2 }, height = 22,
            layout: SimpleLayout [ axis = x, spacing = 5 ],

            // "Declare" is the way home — navigate() resolves against the
            // distro root, so this works on either host at any mount point

            Text [ fontFamily = ["system-ui", "sans-serif"], fontSize = 18,
                fontWeight = semibold, letterSpacing = { -0.02 * this.fontSize }, wrap = false,
                textFill = { gradient("90deg", this.$provided("theme").accent, this.$provided("theme").accentSecondary) }, text = "Declare",
                onClick() { this.root.navigate("apps/homepage/homepage.declare") }
                ],
            Text [ fontFamily = ["system-ui", "sans-serif"], fontSize = 18,
                fontWeight = semibold, letterSpacing = { -0.02 * this.fontSize }, wrap = false,
                textColor = { this.$provided("theme").text }, text = "Docs" ]
            ],

        // the pill: search-as-you-type over the whole corpus; Enter opens the
        // first hit; ⌘K focuses it from anywhere (the Keys source above)

        /* The pill is a VIEW; the input lives in its FLAT ZONE. TextInput's
           `padding` is uniform (16px of it would crush a 32px field), so the
           capsule shape and the text inset split: the wrapper draws the
           chrome — surface fill, the themed line that turns accent while the
           field inside holds focus — and the field starts exactly where the
           cap ends (x = the 16px radius), transparent chrome of its own.
           The field's own fill stays the surface tone (it paints only inside
           the flat zone, so its square corners are invisible) because the
           editable's colorScheme derives from ITS view's fill — that is what
           keeps the native caret and placeholder legible in dark. */

        /* The pill CENTERS in the window but never collides: its span is the
           gap between the brand and whatever the right cluster starts with
           (measured off those views, not a breakpoint — a longer brand or a
           wider stepper moves the bound by itself), and the centered x is
           clamped into that gap. Below `compact` the stepper stands down (the
           reading zoom is the most droppable control; the theme switch and the
           search are not), which is what keeps the pill usable at 560. */

        search: View [ y = { (this.root.barH - 32) / 2 }, height = 32, cornerRadius = 16,
            lo: number = { parent.brand.x + parent.brand.width + 16 },
            hi: number = { (this.root.compact ? parent.themeSwitch.x : parent.size.x) - 16 },
            x = { Math.max(this.lo, Math.min((this.root.hostWidth - this.width) / 2, this.hi - this.width)) },
            width = { Math.max(120, Math.min(440, this.hi - this.lo)) },
            fill = { this.$provided("theme").surface },
            stroke = { stroke(1, this.field.focused ? this.$provided("theme").accent : this.$provided("theme").line) },
            field: TextInput [ x = 16, y = 1, width = { parent.width - 32 }, height = { parent.height - 2 },   // 1px in from the wrapper's stroke, or the field's fill paints over it
                fill = { this.$provided("theme").surface }, stroke = null, cornerRadius = 0, padding = 0,
                fontSize = 14, textColor = { this.$provided("theme").text },
                placeholder = "Search the docs…   ⌘K",
                onInput(t: string) { this.root.searchQ = "" + t; this.root.searchSel = -1 },
                onEnter() { if (this.root.searchHits.length > 0) this.root.openResult(this.root.searchHits[0].loc) },
                onKeyDown(e: KeyEvent) {
                    if (e.key == "Escape") this.root.dismissSearch()
                    else if (e.key == "ArrowDown" && this.root.searchHits.length > 0) this.root.focusHit(0)
                    }
                ]
            ],

        size: View [ y = { (this.root.barH - 30) / 2 }, x = { parent.themeSwitch.x - this.width - 20 }, height = 30,
            visible = { !this.root.compact },
            width = { this.contentWidth },
            cornerRadius = 8, fill = { this.$provided("theme").surface }, stroke = { stroke(1, this.$provided("theme").line) },
            layout: SimpleLayout [ axis = x, spacing = 0 ],
            SizeBtn [ glyph = 11, delta = -0.1 ],
            d1: View [ width = 1, height = 18, y = 6, fill = { this.$provided("theme").line } ],
            SizeBtn [ glyph = 15, delta = 0 ],
            d2: View [ width = 1, height = 18, y = 6, fill = { this.$provided("theme").line } ],
            SizeBtn [ glyph = 19, delta = 0.1 ]
            ],

        themeSwitch: Segmented [ y = { (this.root.barH - 30) / 2 }, x = { this.root.hostWidth - 96 - 16 },
            height = 30, width = 96, iconSize = 15,
            value = { this.root.themeMode },
            input(v: object) { this.root.themeMode = "" + v },
            choices = { [ ({ id: "light",  icon: "SunIcon" }),
                          ({ id: "system", icon: "AutoIcon" }),
                          ({ id: "dark",   icon: "MoonIcon" }) ] }
            ]
        ],

    /* ## The left rail
       Below the bar: the Guide/Reference switch, then the nav for the live
       mode. (Brand and the display controls live in the bar now.) */

    rail: View [ x = 0, y = { this.root.barH }, width = { this.root.railW }, height = { this.root.hostHeight - this.root.barH }, scrolls = y, fill = { this.$provided("theme").rail },
        edge: View [ x = { this.root.railW - 1 }, y = 0, width = 1, height = { parent.height }, fill = { this.$provided("theme").edge } ],
        col: View [ x = 16, y = 16, width = { this.root.railW - 32 },
            layout: SimpleLayout [ axis = y, spacing = 4 ],

            // Guide / Reference. This was a segmented control in every respect
            // except being one: two hand-styled `View`s, so no focus, no tab
            // stop, no keyboard, no press state (register D10). The delivery
            // seam already fit — the pair's value is `app.mode`, deriving from
            // `app.location`, so a pick writes the location and the value comes
            // back round, which is the single source of truth the location
            // comment above asks for.

            // Two tabs. The language pages are a third MODE (their own locations,
            // `language/<form>`) but not a third tab: they live at the top of the
            // reference rail, so the Reference tab lights for both.

            modes: Segmented [ width = { parent.width }, height = 30,
                value = { this.root.mode == "language" ? "reference" : this.root.mode },
                input(v: object) {
                    this.root.location = ("" + v) == "guide" ? "guide/" + this.root.guideAt : "reference/" + this.root.refAt
                    this.root.showPage()
                    },

                // each half declares WHERE it goes, so the switch is a link the
                // crawler can follow — without it the reference half of the docs
                // is unreachable from the default location (see SegmentedItem)

                choices = { [ ({ id: "guide",     label: "Guide",     location: "guide/" + this.root.guideAt }),
                              ({ id: "reference", label: "Reference", location: "reference/" + this.root.refAt }) ] }
                ],

            // guide nav — the parts, each a fold over its chapters

            guideNav: View [ width = { parent.width }, visible = { this.root.mode == "guide" },
                layout: SimpleLayout [ axis = y, spacing = 2 ],
                g1: View [ height = 10 ],
                PartGroup [ datapath = :guideParts[] ]
                ],

            // reference nav — LANGUAGE (the forms, by group, with the index above
            // them) then CLASSES (by topic: model.classGroups). Each group folds.

            refNav: View [ width = { parent.width }, visible = { this.root.mode == "reference" || this.root.mode == "language" },
                layout: SimpleLayout [ axis = y, spacing = 2 ],
                g1:    View [ height = 14 ],
                langEyebrow: Mono [ fontSize = 12, letterSpacing = 1.4, fontWeight = semibold, textColor = { this.$provided("theme").textMuted }, text = "LANGUAGE" ],
                g2:    View [ height = 4 ],
                idx: View [ width = { parent.width }, height = 28, cornerRadius = 6,
                    lit: boolean = { this.root.mode == "language" && this.root.form == "" },
                    fill = { this.lit ? this.$provided("theme").sel : this.hovered ? this.$provided("theme").control : null },
                    link = "#language/",
                    onClick() { this.root.formAt = ""; this.root.location = "language/"; this.root.showPage() },
                    Text [ x = 24, y = 6, fontFamily = ["system-ui", "sans-serif"], fontSize = 14, wrap = false, text = "All forms", textColor = { parent.lit ? this.$provided("theme").text : this.$provided("theme").tabIdle } ]
                    ],
                FormGroup [ datapath = :forms.groups[] ],
                g3:    View [ height = 18 ],
                classEyebrow: Mono [ fontSize = 12, letterSpacing = 1.4, fontWeight = semibold, textColor = { this.$provided("theme").textMuted }, text = "CLASSES" ],
                g4:    View [ height = 4 ],
                ClassGroup [ datapath = :classGroups[] ]
                ]
            ]
        ],

    /* ## The detail pane
       Its own scroller. Guide chapters are light shells (each fetches and
       builds its content only once visibility asks — ChapterDetail); the
       reference is ONE page, re-rooted to the selection (refCol). So the
       scroller only ever measures what is actually being read.
       `selectable` (a provided value) opts the whole right pane into ordinary
       browser text selection — prose, signatures, Markdown runs — while the
       rail stays chrome.

       SEARCH REPLACES THE CONTENT (ruled 2026-08-08): while the query is
       non-empty the reading column hides and the results page takes the pane
       — same column, same scroller, no overlay chrome. Clearing the query
       (Escape, opening a result, deleting the text) brings the page back
       exactly as it was: `visible` conceals, it never tears down. No matches
       (or the index still loading) says so in the middle of the pane. */

    detail: View [ x = { this.root.railW }, y = { this.root.barH }, width = { this.root.hostWidth - this.root.railW }, height = { this.root.hostHeight - this.root.barH }, scrolls = y, selectable = true,
        top: View [ x = 0, y = 0, width = 1, height = 1 ],       // showPage's scroll-to-top anchor
        col: View [ x = 48, y = 40, width = { parent.width - 96 }, visible = { this.root.searchQ == "" },
            guideCol: View [ width = { parent.width }, visible = { this.root.mode == "guide" },
                ChapterDetail [ datapath = :guide[], cid = :id ]
                ],

            /* ONE reference page exists at a time — the selection's (ruled
               2026-08-08). The old shape replicated a ClassDetail per class
               (356 fully-built pages, `visible` picking one): construction
               paid the whole reference at every boot for one visible page.
               The datapath now COMPUTES the selected class's node, so a
               switch re-roots this single subtree and builds just that page;
               the rail (ClassTab, above) still replicates the full list —
               that IS what visibility requires of a navigator. */

            refCol: View [ width = { parent.width }, visible = { this.root.mode == "reference" },
                ClassDetail [ datapath = { (this.root.docs.read(["tree"]) || []).find(c => c.name == this.root.selected) }, cname = :name ]
                ],

            // the language pane: the index (no cursor) or ONE form's page, re-rooted to
            // the selection exactly as the reference page is

            langCol: View [ width = { parent.width }, visible = { this.root.mode == "language" },
                FormIndex [ datapath = { this.root.docs.read(["forms"]) } ],
                FormDetail [ datapath = { ((this.root.docs.read(["forms", "pages"]) || {}))[this.root.form] }, slug = { "" + this.$data(["slug"]) } ]
                ]
            ],

        // the results page — rows replicate off the computed hits (the
        // homepage's value-root + :items[] idiom); focusHit walks these
        // children, so this column is the one place rows live

        searchCol: View [ x = 48, y = 24, width = { parent.width - 96 },
            visible = { this.root.searchQ != "" && this.root.searchHits.length > 0 },
            layout: SimpleLayout [ axis = y, spacing = 2 ],
            datapath = { this.root.hits.value },
            SearchHit [ datapath = :items[], width = { parent.width } ]
            ],

        // the empty answer, centered in the pane — visible only once the
        // index has answered (before that, the honest "loading")

        noHits: View [ visible = { this.root.searchQ != "" && this.root.searchHits.length == 0 },
            x = 0, y = 0, width = { parent.width }, height = { parent.height },
            msg: Muted [ x = center, y = center, fontSize = 14,
                text = { this.root.searchIdx.loaded ? "No matches — the corpus has nothing for “" + this.root.searchQ + "”." : "Loading the search index…" } ]
            ]
        ]
    ,
    // the traveling focus indicator — provided with the component library

    FocusRing [ ],
]
